import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { runWorktreeCommand } from "../src/worktrunk/command.js";
import { recordVerification } from "../src/worktrunk/verification.js";
const git = (cwd: string, ...a: string[]) => execFileSync("git", a, { cwd, encoding: "utf8", stdio: ["ignore","pipe","pipe"] }).trim();
function mk(viaLink = false, cfg?: any) {
  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "probe-")));
  const real = path.join(root, "proj"); const home = path.join(root, "home");
  fs.mkdirSync(real); fs.mkdirSync(home);
  git(real, "init", "-q", "-b", "main"); git(real, "config", "user.email", "t@e.com"); git(real, "config", "user.name", "T"); git(real,"config","commit.gpgsign","false");
  fs.writeFileSync(path.join(real, "a.txt"), "1\n"); git(real, "add", "."); git(real, "commit", "-q", "-m", "init");
  const repo = viaLink ? path.join(root, "link") : real;
  if (viaLink) fs.symlinkSync(real, repo);
  if (cfg) { fs.mkdirSync(path.join(home, ".config/nexus"), { recursive: true }); fs.writeFileSync(path.join(home, ".config/nexus/config.json"), JSON.stringify(cfg)); }
  const wt = (cwd: string, args: string[]) => runWorktreeCommand(args, { cwd, home, readOnly: false });
  return { root, real, repo, home, wt };
}
const commit = (d: string, f: string) => { fs.writeFileSync(path.join(d, f), f); git(d, "add", f); git(d, "commit", "-q", "-m", f); };
for (const [name, link, cfg] of [["plain", false, undefined], ["symlinked repo path", true, undefined], ["sibling layout", false, { version: 1, worktree: { layout: "sibling" } }]] as any) {
  test(`named nexus/foo merges (${name}) with waiver and receipt`, () => {
    const f = mk(link, cfg);
    const made = f.wt(f.repo, ["switch", "-c", "nexus/foo", "--no-copy"]); assert.ok(made.success, made.output);
    const dir = (made as any).data.path; console.log(name, dir);
    commit(dir, "x.txt");
    const real = fs.realpathSync(dir);
    // receipt
    assert.equal(recordVerification(real, "npm test"), true);
    let r = f.wt(real, ["merge", "--no-remove"]); assert.ok(r.success, "receipt: " + r.output);
    commit(real, "y.txt");
    r = f.wt(real, ["merge", "--no-remove", "--no-verify-receipt", "--reason", "waiver ok"]); assert.ok(r.success, "waiver: " + r.output);
    // remove works w/o --force
    r = f.wt(f.repo, ["remove", "nexus/foo"]); assert.ok(r.success, "remove: " + r.output);
  });
}
test("task shapes refused; prune skips; remove needs force; plain-git nexus branch outside .nexus is mergeable", () => {
  const f = mk();
  const base = path.join(f.repo, ".nexus", "worktrees"); fs.mkdirSync(path.join(base, "op-k", "units"), { recursive: true });
  const shapes: [string,string][] = [["nexus/t1", path.join(base, "t1")], ["nexus/op-k/u1", path.join(base,"op-k","units","u1")], ["nexus/op-k/u1-3", path.join(base,"op-k","units","u9")], ["nexus/op-k/integration", path.join(base,"op-k","integration")]];
  for (const [b, p] of shapes) { git(f.repo, "worktree", "add", "-q", "-b", b, p); commit(p, b.replace(/\//g,"_")); }
  const other = f.wt(f.repo, ["switch", "-c", "feat/o", "--no-copy"]) as any; commit(other.data.path, "o.txt");
  for (const [b, p] of shapes) {
    let r = f.wt(other.data.path, ["merge", b, "--no-remove", "--no-verify-receipt", "--reason", "waiver ok"]); assert.ok(!r.success && /speculative/.test(r.output), b + r.output);
    r = f.wt(f.repo, ["remove", b]); assert.ok(!r.success && /speculative/.test(r.output), "remove " + b + r.output);
    // merge from inside the task worktree
    r = f.wt(p, ["merge", "--no-remove", "--no-verify-receipt", "--reason", "waiver ok"]); assert.ok(!r.success && /speculative/.test(r.output), "inside " + b + r.output);
  }
  const pr = f.wt(f.repo, ["prune", "--min-age", "0s", "--dry-run"]); console.log(pr.output);
  for (const [b] of shapes) assert.match(pr.output, new RegExp(b.replace(/\//g,"\\/") + ".*speculative|speculative.*" + b.replace(/\//g,"\\/")));
  // unregistered nexus/ branch at outside sibling path: not a task
  const sib = path.join(f.root, "sib"); git(f.repo, "worktree", "add", "-q", "-b", "nexus/ext", sib); commit(sib, "e.txt");
  const r = f.wt(sib, ["merge", "--no-remove", "--no-verify-receipt", "--reason", "waiver ok"]); console.log("ext:", r.success, r.output.slice(0,200));
  // crafted: task path with named-looking dir name inside base
  const fake = path.join(base, "nexus-foo"); git(f.repo, "worktree", "add", "-q", "-b", "nexus/foo", fake); commit(fake, "z.txt");
  const r2 = f.wt(fake, ["merge", "--no-remove", "--no-verify-receipt", "--reason", "waiver ok"]); console.log("unregistered nexus-foo path:", r2.success, r2.output.slice(0,200));
});
EOF
